import './correcciones-preview-20260906.js';
import './correcciones-funcionales-20260906.js';
import './correcciones-definitivas-20260906.js';
import { state, todayISO } from '../state.js';
import { fmtMoney, fmtDate, clienteNombre, chipPago } from '../ui.js';
import { escHtml } from '../sanitize.js';
if (!window.__smFinal0906) { window.__smFinal0906 = true; queueMicrotask(instalar); }
function fechaCobroReal(o){if(o?.fechaPago)return String(o.fechaPago).slice(0,10);return o?.fechaIngreso?String(o.fechaIngreso).slice(0,10):'';}
function enRango(fecha,desde,hasta){return !!fecha&&(!desde||fecha>=desde)&&(!hasta||fecha<=hasta);}
function corregirTablaFinanzas(){const tabla=document.getElementById('finanzas-ordenes-table');if(!tabla)return;const desde=document.getElementById('sm-fdesde')?.value||todayISO(0);const hasta=document.getElementById('sm-fhasta')?.value||todayISO(0);if(desde>hasta)return;const ordenes=(state.ordenes||[]).filter(o=>enRango(fechaCobroReal(o),desde,hasta)).sort((a,b)=>(fechaCobroReal(b)+String(b.numero).padStart(8,'0')).localeCompare(fechaCobroReal(a)+String(a.numero).padStart(8,'0')));tabla.innerHTML='<thead><tr><th>Fecha</th><th>Orden</th><th>Cliente</th><th>Precio</th><th>Pagado</th><th>Pendiente</th><th>Método</th><th>Estado</th></tr></thead><tbody>'+ordenes.map(o=>{const total=Number(o.precio)-Number(o.descuento||0);const pendiente=Math.max(total-Number(o.pagado||0),0);return '<tr><td data-label="Fecha">'+fmtDate(fechaCobroReal(o))+'</td><td class="mono" data-label="Orden">#'+escHtml(o.numero)+'</td><td data-label="Cliente">'+escHtml(clienteNombre(o.clienteId))+'</td><td data-label="Precio">'+fmtMoney(total)+'</td><td data-label="Pagado">'+fmtMoney(o.pagado)+'</td><td data-label="Pendiente">'+fmtMoney(pendiente)+'</td><td data-label="Método">'+escHtml(o.metodoPago||'—')+'</td><td data-label="Estado">'+chipPago(o.estadoPago)+'</td></tr>';}).join('')+'</tbody>';}
function corregirResumenReportes(){const qr=document.getElementById('rep-qr');const ef=document.getElementById('rep-ef');if(!qr||!ef)return;const desde=document.getElementById('rep-desde')?.value||'';const hasta=document.getElementById('rep-hasta')?.value||'';const ordenes=(state.ordenes||[]).filter(o=>{const fecha=o?.fechaPago?String(o.fechaPago).slice(0,10):'';return Number(o.pagado||0)>0&&((!desde&&!hasta)||enRango(fecha,desde,hasta));});qr.textContent=fmtMoney(ordenes.reduce((s,o)=>s+Number(o.pagadoQR||0),0));ef.textContent=fmtMoney(ordenes.reduce((s,o)=>s+Number(o.pagadoEfectivo||0),0));}
function envolver(nombre,despues){const original=window[nombre];if(typeof original!=='function'||original.__smFinal0906)return;const wrapper=function(...args){const r=original.apply(this,args);if(r&&typeof r.then==='function')return r.then(v=>{despues();return v;});despues();return r;};wrapper.__smFinal0906=true;window[nombre]=wrapper;}
function instalar(){envolver('renderFinanzas',corregirTablaFinanzas);envolver('renderReportes',corregirResumenReportes);envolver('setRepRange',corregirResumenReportes);corregirTablaFinanzas();corregirResumenReportes();}
